create extension if not exists "pg_cron" with schema "pg_catalog";

drop extension if exists "pg_net";

create extension if not exists "pg_net" with schema "public";


  create table "public"."posts" (
    "id" bigint generated by default as identity not null,
    "title" text,
    "image_url" text,
    "created_at_boh" timestamp with time zone default now(),
    "size" text,
    "color" text,
    "quantity" integer,
    "location" text,
    "name" text,
    "image_path" text,
    "in_progress" text,
    "comment" text,
    "repost" boolean not null default false,
    "created_at_foh" timestamp with time zone default now()
      );



  create table "public"."tokens" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "token" text
      );


CREATE UNIQUE INDEX "Tokens_pkey" ON public.tokens USING btree (id);

CREATE UNIQUE INDEX posts_pkey ON public.posts USING btree (id);

alter table "public"."posts" add constraint "posts_pkey" PRIMARY KEY using index "posts_pkey";

alter table "public"."tokens" add constraint "Tokens_pkey" PRIMARY KEY using index "Tokens_pkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.call_cleanup_image()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM
    net.http_post(
      url := 'https://qbbbsznsxhfllwhborju.supabase.co/functions/v1/cleanup-post-image',
      headers := '{"Content-Type":"application/json"}',
      body := json_build_object(
        'image_path', OLD.image_path
      )::text
    );
  RETURN OLD;
END;
$function$
;

