  create policy "Enable insert for authenticated users only"
  on "public"."posts"
  as permissive
  for insert
  to anon
with check (true);



  create policy "Enable read access for all users"
  on "public"."posts"
  as permissive
  for select
  to anon
using (true);



  create policy "Allow public delete from uploads bucket"
  on "storage"."objects"
  as permissive
  for delete
  to public
using ((bucket_id = 'uploads'::text));



  create policy "Allow public read access"
  on "storage"."objects"
  as permissive
  for select
  to public
using ((bucket_id = 'uploads'::text));



  create policy "Allow uploads for all users"
  on "storage"."objects"
  as permissive
  for insert
  to public
with check ((bucket_id = 'uploads'::text));



